UPDATE ai_cultural_rules SET criterion='cach_tan',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R07","level":"consider","criterion":"cach_tan","when":{"all":[{"garment":["ao_ngu_than"]},{"hasAccessory":"sneaker"}]},"reason":"Cách tân chấp nhận được, nên giữ cổ đứng và 5 khuy","suggestion":{"text":"Chọn sneaker trắng trơn, giữ cổ đứng và đủ 5 khuy"},"sources":["https://visithue.vn/Tinh-te-ao-dai-ngu-than.html/?pid=MjA1MjR8Y3NkbGRs0"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.","title":"Cách tân chấp nhận được, nên giữ cổ đứng và 5 khuy","group":"sneaker_style","priority":1,"points":-10,"scope":"styling"}' AS JSONB) WHERE rule_key='R07';
