UPDATE ai_cultural_rules SET criterion='boi_canh',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R12","level":"consider","criterion":"boi_canh","when":{"all":[{"occasion":["dam_cuoi","tet"]},{"allColorsIn":["trang_nga","trang_tinh"]},{"hasAccessory":"khan_van"}]},"reason":"Áo và lớp dưới cùng thuộc nhóm trắng, kèm khăn vấn, tạo một hướng phối đơn sắc trong dịp Tết hoặc cưới; nên đối chiếu dress code cụ thể.","suggestion":{"text":"Nếu muốn tổng thể có điểm nhấn vui tươi, thêm màu ở áo hoặc phụ kiện. Không thể kết luận tang phục chỉ từ cặp màu và loại khăn."},"sources":[],"verified":false,"sourceNote":"Gợi ý phối đồ hoặc sử dụng của ứng dụng; chưa có nguồn đối chiếu cho nhận định này.","title":"Toàn màu trắng kèm khăn trắng gợi liên tưởng tang phục","group":"R12","priority":1,"points":-10,"scope":"styling"}' AS JSONB) WHERE rule_key='R12';
