UPDATE ai_cultural_rules SET criterion='boi_canh',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R15","level":"consider","criterion":"boi_canh","when":{"all":[{"all":[{"garment":["nhat_binh"]},{"occasion":["dao_pho"]}]},{"style":["truyen_thong"]},{"role":["khach","nhan_vat_chinh","be_trap","nhom"]}]},"reason":"Nhật Bình có dáng lễ phục rõ nét; khi đi dạo với mục tiêu phối truyền thống, tổng thể có thể trang trọng hơn hoạt động đã chọn.","suggestion":{"text":"Giữ Nhật Bình nếu mục đích là chụp ảnh cổ phục; nếu cần di chuyển gọn, cân nhắc áo dài hoặc bà ba. Đây là lựa chọn theo mục đích mặc."},"sources":["https://khamphahue.com.vn/Hue-24h/Thong-bao/tid/Ao-Nhat-Binh-Mot-di-san-van-hoa-quy-cua-Co-do-Hue.html/pid/11533/cid/28"],"verified":false,"sourceNote":"Nguồn giới thiệu lịch sử và đặc trưng trang phục. Gợi ý phối đồ và điểm số là quy tắc tham khảo của ứng dụng, chưa được nguồn này xác nhận toàn bộ.","title":"Vốn là lễ phục cung đình triều Nguyễn","group":"R15","priority":1,"points":-10,"scope":"styling"}' AS JSONB) WHERE rule_key='R15';
