UPDATE ai_cultural_rules SET criterion='cau_truc',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R56","title":"Váy dài với áo dài hoặc ngũ thân","level":"consider","criterion":"cau_truc","group":"bottom_shape","priority":2,"points":-8,"scope":"styling","when":{"all":[{"garment":["ao_dai","ao_ngu_than"]},{"bottom":["vay_dai"]}]},"reason":"Váy dài thay lớp quần tạo một biến thể cách tân; tổng thể khác cấu trúc áo mặc ngoài quần thường gặp.","suggestion":{"text":"Giữ váy nếu chủ đích là cách tân; chọn quần dài để trở về hướng phối truyền thống. Không coi mọi biến thể là sai."},"sources":["https://vietnam.travel/things-to-do/ao-dai-vietnam"],"verified":false,"sourceNote":"Nguồn mô tả trang phục và bối cảnh lịch sử. Điều kiện phối đồ, mức cộng/trừ điểm là quy tắc tham khảo của ứng dụng, không phải điều cấm được nguồn xác nhận."}' AS JSONB) WHERE rule_key='R56';
