UPDATE ai_cultural_rules SET criterion='boi_canh',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R57","title":"Chưa chọn giày cho dịp lễ","level":"consider","criterion":"boi_canh","group":"shoe_formality","priority":2,"points":-8,"scope":"context","when":{"all":[{"occasion":["tet","ky_yeu"]},{"shoes":["khong"]}]},"reason":"Bản phối cho Tết hoặc kỷ yếu chưa có giày dép; phần đánh giá mới phản ánh lựa chọn trên màn hình.","suggestion":{"text":"Chọn giày bệt, hài hoặc giày kín phù hợp hoạt động thực tế."},"sources":[],"verified":false,"sourceNote":"Quy tắc phối đồ của ứng dụng, dựa trên các món đã chọn và bối cảnh đã cung cấp; không phải quy định văn hóa bắt buộc."}' AS JSONB) WHERE rule_key='R57';
