UPDATE ai_cultural_rules SET criterion='boi_canh',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R70","title":"Nhật Bình cho nhân vật chính lễ cưới","level":"ok","criterion":"boi_canh","group":"dress_occasion","priority":2,"points":5,"scope":"context","when":{"all":[{"occasion":["dam_cuoi"]},{"role":["nhan_vat_chinh"]},{"garment":["nhat_binh"]}]},"reason":"Vai trò nhân vật chính phù hợp mục đích chọn Nhật Bình làm điểm nhấn lễ phục hiện đại.","suggestion":{"text":"Phối lớp dưới dài và chọn phụ kiện theo mức trang trọng của buổi lễ."},"sources":["https://khamphahue.com.vn/Hue-24h/Thong-bao/tid/Ao-Nhat-Binh-Mot-di-san-van-hoa-quy-cua-Co-do-Hue.html/pid/11533/cid/28"],"verified":false,"sourceNote":"Nguồn mô tả trang phục và bối cảnh lịch sử. Điều kiện phối đồ, mức cộng/trừ điểm là quy tắc tham khảo của ứng dụng, không phải điều cấm được nguồn xác nhận."}' AS JSONB) WHERE rule_key='R70';
