UPDATE ai_cultural_rules SET criterion='boi_canh',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R80","title":"Hai mảng tối cho ảnh ngoài trời buổi tối","level":"consider","criterion":"boi_canh","group":"color_night","priority":2,"points":-5,"scope":"context","when":{"all":[{"setting":["ngoai_troi","ca_hai"]},{"timeOfDay":["buoi_toi"]},{"metric":{"name":"mainLightness","max":0.34}},{"metric":{"name":"bottomLightness","max":0.34}}]},"reason":"Cả hai mảng có độ sáng OKLCH thấp trong bối cảnh ảnh ngoài trời buổi tối; chi tiết có thể khó tách nếu thiếu ánh sáng.","suggestion":{"text":"Tăng sáng một mảng hoặc kiểm tra ánh sáng tại điểm chụp; ứng dụng không đo ánh sáng môi trường."},"sources":[],"verified":false,"sourceNote":"Quy tắc phối đồ của ứng dụng, dựa trên các món đã chọn và bối cảnh đã cung cấp; không phải quy định văn hóa bắt buộc."}' AS JSONB) WHERE rule_key='R80';
