UPDATE ai_cultural_rules SET criterion='phu_kien',active=TRUE,verified=FALSE,metadata=CAST('{"id":"R96","title":"Tứ thân với khăn và nón quai thao","level":"ok","criterion":"phu_kien","group":"cultural_accessory_set","priority":2,"points":10,"scope":"styling","when":{"all":[{"garment":["ao_tu_than"]},{"hasAccessory":"non_quai_thao"},{"hasAccessory":"khan_mo_qua"}]},"reason":"Khăn mỏ quạ và nón quai thao tạo hướng phối tứ thân gắn với hình ảnh Quan họ của ứng dụng.","suggestion":{"text":"Giữ tổng thể nhiều lớp gọn; tham khảo tư liệu địa phương nếu cần phục dựng đúng một hình thức trình diễn."},"sources":["https://dsvh.gov.vn/dan-ca-quan-ho-bac-ninh-482"],"verified":false,"sourceNote":"Nguồn mô tả trang phục và bối cảnh lịch sử. Điều kiện phối đồ, mức cộng/trừ điểm là quy tắc tham khảo của ứng dụng, không phải điều cấm được nguồn xác nhận."}' AS JSONB) WHERE rule_key='R96';
